#!/usr/bin/env node
/**
 * Wraps the exact `createBodyLayer()` code generated by Blockbench MCP's
 * `bbmodel_export_modded_entity` (`template: "1.17"`, `flip_y: true`) into
 * production Forge 1.20.1 Mojmap `EntityModel` classes with multi-bone
 * biomechanical animations:
 *   - `mod/src/main/java/ru/aiforge/riftworld/client/model/LiopleurodonBlockbenchModel.java`
 *   - `mod/src/main/java/ru/aiforge/riftworld/client/model/PegasusBlockbenchModel.java`
 */

import { mkdirSync, readFileSync, writeFileSync } from "node:fs";
import { dirname, join, resolve } from "node:path";
import { fileURLToPath } from "node:url";

const HERE = dirname(fileURLToPath(import.meta.url));
const ROOT = resolve(HERE, "..", "..");

function extractCreateBodyLayer(rawCode) {
  const start = rawCode.indexOf("\tpublic static LayerDefinition createBodyLayer()");
  const endMarker = "\t@Override\n\tpublic void setupAnim(";
  const end = rawCode.indexOf(endMarker);
  if (start < 0 || end < 0) {
    throw new Error("Could not locate createBodyLayer() in raw Blockbench export");
  }
  return rawCode.slice(start, end).trimEnd();
}

function buildLiopleurodonJava(rawCode) {
  const bodyLayerMethod = extractCreateBodyLayer(rawCode);
  return `package ru.aiforge.riftworld.client.model;

import com.mojang.blaze3d.vertex.PoseStack;
import com.mojang.blaze3d.vertex.VertexConsumer;
import java.util.List;
import net.minecraft.client.model.EntityModel;
import net.minecraft.client.model.geom.ModelLayerLocation;
import net.minecraft.client.model.geom.ModelPart;
import net.minecraft.client.model.geom.PartPose;
import net.minecraft.client.model.geom.builders.CubeDeformation;
import net.minecraft.client.model.geom.builders.CubeListBuilder;
import net.minecraft.client.model.geom.builders.LayerDefinition;
import net.minecraft.client.model.geom.builders.MeshDefinition;
import net.minecraft.client.model.geom.builders.PartDefinition;
import net.minecraft.resources.ResourceLocation;
import net.minecraft.util.Mth;
import ru.aiforge.riftworld.RiftWorld;
import ru.aiforge.riftworld.entity.LiopleurodonEntity;

/**
 * Generated via Blockbench MCP headless 1.10.1 (\`bbmodel_export_modded_entity\`, Mojmap 1.17+ / 1.20.1):
 * 24 articulated bones, 234 sculpted cuboids, 1024x1024 zero-overlap UV atlas.
 */
public class LiopleurodonBlockbenchModel extends EntityModel<LiopleurodonEntity> {
\tpublic static final ModelLayerLocation LAYER_LOCATION =
\t\t\tnew ModelLayerLocation(new ResourceLocation(RiftWorld.MODID, "liopleurodon_bb"), "main");

\tprivate record RestPose(ModelPart part, float x, float y, float z) {}

\tprivate final ModelPart root;
\tprivate final ModelPart body_front;
\tprivate final ModelPart body_mid;
\tprivate final ModelPart body_rear;
\tprivate final ModelPart fin_back_1_l;
\tprivate final ModelPart fin_back_2_l;
\tprivate final ModelPart fin_back_3_l;
\tprivate final ModelPart fin_back_1_r;
\tprivate final ModelPart fin_back_2_r;
\tprivate final ModelPart fin_back_3_r;
\tprivate final ModelPart tail_1;
\tprivate final ModelPart tail_2;
\tprivate final ModelPart tail_3;
\tprivate final ModelPart tail_fluke;
\tprivate final ModelPart neck_base;
\tprivate final ModelPart neck_front;
\tprivate final ModelPart head;
\tprivate final ModelPart jaw;
\tprivate final ModelPart fin_front_1_l;
\tprivate final ModelPart fin_front_2_l;
\tprivate final ModelPart fin_front_3_l;
\tprivate final ModelPart fin_front_1_r;
\tprivate final ModelPart fin_front_2_r;
\tprivate final ModelPart fin_front_3_r;
\tprivate final List<RestPose> restPoses;

\tpublic LiopleurodonBlockbenchModel(ModelPart bakedRoot) {
\t\tthis.root = bakedRoot.getChild("root");
\t\tthis.body_front = this.root.getChild("body_front");
\t\tthis.body_mid = this.body_front.getChild("body_mid");
\t\tthis.body_rear = this.body_mid.getChild("body_rear");
\t\tthis.fin_back_1_l = this.body_rear.getChild("fin_back_1_l");
\t\tthis.fin_back_2_l = this.fin_back_1_l.getChild("fin_back_2_l");
\t\tthis.fin_back_3_l = this.fin_back_2_l.getChild("fin_back_3_l");
\t\tthis.fin_back_1_r = this.body_rear.getChild("fin_back_1_r");
\t\tthis.fin_back_2_r = this.fin_back_1_r.getChild("fin_back_2_r");
\t\tthis.fin_back_3_r = this.fin_back_2_r.getChild("fin_back_3_r");
\t\tthis.tail_1 = this.body_rear.getChild("tail_1");
\t\tthis.tail_2 = this.tail_1.getChild("tail_2");
\t\tthis.tail_3 = this.tail_2.getChild("tail_3");
\t\tthis.tail_fluke = this.tail_3.getChild("tail_fluke");
\t\tthis.neck_base = this.body_front.getChild("neck_base");
\t\tthis.neck_front = this.neck_base.getChild("neck_front");
\t\tthis.head = this.neck_front.getChild("head");
\t\tthis.jaw = this.head.getChild("jaw");
\t\tthis.fin_front_1_l = this.body_front.getChild("fin_front_1_l");
\t\tthis.fin_front_2_l = this.fin_front_1_l.getChild("fin_front_2_l");
\t\tthis.fin_front_3_l = this.fin_front_2_l.getChild("fin_front_3_l");
\t\tthis.fin_front_1_r = this.body_front.getChild("fin_front_1_r");
\t\tthis.fin_front_2_r = this.fin_front_1_r.getChild("fin_front_2_r");
\t\tthis.fin_front_3_r = this.fin_front_2_r.getChild("fin_front_3_r");
\t\tthis.restPoses = this.root.getAllParts()
\t\t\t\t.map(p -> new RestPose(p, p.xRot, p.yRot, p.zRot))
\t\t\t\t.toList();
\t}

${bodyLayerMethod}

\tprivate static float rad(float deg) {
\t\treturn deg * ((float) Math.PI / 180.0F);
\t}

\t/** Applies Blockbench Y-up degree offsets (\`-rx, -ry, +rz\` in Mojang ModelPart space). */
\tprivate static void addBbDeg(ModelPart p, float dx, float dy, float dz) {
\t\tp.xRot -= rad(dx);
\t\tp.yRot -= rad(dy);
\t\tp.zRot += rad(dz);
\t}

\t@Override
\tpublic void setupAnim(LiopleurodonEntity entity, float limbSwing, float limbSwingAmount,
\t                      float ageInTicks, float netHeadYaw, float headPitch) {
\t\tfor (RestPose rp : this.restPoses) {
\t\t\trp.part.xRot = rp.x;
\t\t\trp.part.yRot = rp.y;
\t\t\trp.part.zRot = rp.z;
\t\t}

\t\tif (entity.isNoAi()) {
\t\t\t// Natural museum/showcase pelagic poise (gentle S-curve + menacingly parted jaws)
\t\t\tfloat idle = Mth.sin(ageInTicks * 0.05F);
\t\t\taddBbDeg(neck_base, 0.0F, 2.0F, 0.0F);
\t\t\taddBbDeg(neck_front, 0.0F, 2.5F, 0.0F);
\t\t\taddBbDeg(head, 1.5F, 2.5F, -1.5F);
\t\t\taddBbDeg(jaw, -7.5F - 1.5F * idle, 0.0F, 0.0F);
\t\t\taddBbDeg(body_mid, 0.0F, -2.5F, 0.0F);
\t\t\taddBbDeg(body_rear, 0.0F, -4.0F, 0.0F);
\t\t\taddBbDeg(tail_1, 0.0F, -5.5F, 0.0F);
\t\t\taddBbDeg(tail_2, 0.0F, 6.5F, 0.0F);
\t\t\taddBbDeg(tail_3, 0.0F, 9.0F, 0.0F);
\t\t\taddBbDeg(tail_fluke, 0.0F, 8.0F, 0.0F);
\t\t\taddBbDeg(fin_front_1_l, 3.0F, -3.0F, -4.0F + 2.0F * idle);
\t\t\taddBbDeg(fin_front_1_r, -3.0F, 3.0F, 4.0F - 2.0F * idle);
\t\t\treturn;
\t\t}

\t\tfloat speed = 0.11F + limbSwingAmount * 0.14F;
\t\tfloat ph = ageInTicks * speed;
\t\tfloat amp = 0.55F + Math.min(1.0F, limbSwingAmount * 1.4F) * 0.65F;

\t\t// Pelagic S-wave spine & tail propulsion
\t\taddBbDeg(neck_base, 0.0F, Mth.sin(ph + 0.5F) * 3.0F * amp, 0.0F);
\t\taddBbDeg(neck_front, 0.0F, Mth.sin(ph + 0.9F) * 3.5F * amp, 0.0F);
\t\taddBbDeg(head, headPitch * -0.25F, netHeadYaw * -0.20F + Mth.sin(ph + 1.2F) * 3.0F * amp, 0.0F);
\t\taddBbDeg(body_mid, 0.0F, Mth.sin(ph - 0.5F) * 3.5F * amp, 0.0F);
\t\taddBbDeg(body_rear, 0.0F, Mth.sin(ph - 1.1F) * 5.0F * amp, 0.0F);
\t\taddBbDeg(tail_1, 0.0F, Mth.sin(ph - 1.7F) * 7.5F * amp, 0.0F);
\t\taddBbDeg(tail_2, 0.0F, Mth.sin(ph - 2.3F) * 10.5F * amp, 0.0F);
\t\taddBbDeg(tail_3, 0.0F, Mth.sin(ph - 2.9F) * 13.0F * amp, 0.0F);
\t\taddBbDeg(tail_fluke, 0.0F, Mth.sin(ph - 3.4F) * 15.0F * amp, 0.0F);

\t\t// 4-flipper underwater flight figure-8 hydrofoil stroke (pelvic paddles phase-shifted behind pectorals)
\t\tfloat fStroke = Mth.sin(ph);
\t\tfloat fPitch = Mth.cos(ph);
\t\taddBbDeg(fin_front_1_l, fPitch * 8.0F * amp, fStroke * -4.0F, fStroke * 16.0F * amp);
\t\taddBbDeg(fin_front_2_l, fPitch * 4.0F * amp, 0.0F, Mth.sin(ph - 0.5F) * 10.0F * amp);
\t\taddBbDeg(fin_front_3_l, 0.0F, 0.0F, Mth.sin(ph - 0.9F) * 8.0F * amp);

\t\taddBbDeg(fin_front_1_r, fPitch * 8.0F * amp, fStroke * 4.0F, -fStroke * 16.0F * amp);
\t\taddBbDeg(fin_front_2_r, fPitch * 4.0F * amp, 0.0F, -Mth.sin(ph - 0.5F) * 10.0F * amp);
\t\taddBbDeg(fin_front_3_r, 0.0F, 0.0F, -Mth.sin(ph - 0.9F) * 8.0F * amp);

\t\tfloat bStroke = Mth.sin(ph - 1.25F);
\t\tfloat bPitch = Mth.cos(ph - 1.25F);
\t\taddBbDeg(fin_back_1_l, bPitch * 7.0F * amp, bStroke * -3.5F, bStroke * 14.0F * amp);
\t\taddBbDeg(fin_back_2_l, 0.0F, 0.0F, Mth.sin(ph - 1.7F) * 9.0F * amp);
\t\taddBbDeg(fin_back_3_l, 0.0F, 0.0F, Mth.sin(ph - 2.1F) * 7.0F * amp);

\t\taddBbDeg(fin_back_1_r, bPitch * 7.0F * amp, bStroke * 3.5F, -bStroke * 14.0F * amp);
\t\taddBbDeg(fin_back_2_r, 0.0F, 0.0F, -Mth.sin(ph - 1.7F) * 9.0F * amp);
\t\taddBbDeg(fin_back_3_r, 0.0F, 0.0F, -Mth.sin(ph - 2.1F) * 7.0F * amp);

\t\t// Menacing predatory jaw gape + attack snap
\t\tfloat bite = entity.attackAnim > 0.0F ? Mth.sin(entity.attackAnim * (float) Math.PI) * 18.0F : 0.0F;
\t\tfloat breathGape = (Mth.sin(ageInTicks * 0.07F) * 0.5F + 0.5F) * 5.0F;
\t\taddBbDeg(jaw, -(breathGape + bite), 0.0F, 0.0F);
\t}

\t@Override
\tpublic void renderToBuffer(PoseStack poseStack, VertexConsumer vertexConsumer, int packedLight,
\t                           int packedOverlay, float red, float green, float blue, float alpha) {
\t\tthis.root.render(poseStack, vertexConsumer, packedLight, packedOverlay, red, green, blue, alpha);
\t}
}
`;
}

function buildPegasusJava(rawCode) {
  const bodyLayerMethod = extractCreateBodyLayer(rawCode);
  return `package ru.aiforge.riftworld.client.model;

import com.mojang.blaze3d.vertex.PoseStack;
import com.mojang.blaze3d.vertex.VertexConsumer;
import java.util.List;
import net.minecraft.client.model.EntityModel;
import net.minecraft.client.model.geom.ModelLayerLocation;
import net.minecraft.client.model.geom.ModelPart;
import net.minecraft.client.model.geom.PartPose;
import net.minecraft.client.model.geom.builders.CubeDeformation;
import net.minecraft.client.model.geom.builders.CubeListBuilder;
import net.minecraft.client.model.geom.builders.LayerDefinition;
import net.minecraft.client.model.geom.builders.MeshDefinition;
import net.minecraft.client.model.geom.builders.PartDefinition;
import net.minecraft.resources.ResourceLocation;
import net.minecraft.util.Mth;
import ru.aiforge.riftworld.RiftWorld;
import ru.aiforge.riftworld.entity.PegasusEntity;

/**
 * Generated via Blockbench MCP headless 1.10.1 (\`bbmodel_export_modded_entity\`, Mojmap 1.17+ / 1.20.1):
 * 37 articulated bones (including 3-fan feather scissoring sub-bones for zero-clipping Z-folded wings),
 * 179 sculpted cuboids, 512x512 zero-overlap UV atlas, and full 9-state biomechanical animation blending:
 *   1. Living idle (breathing, asymmetric ear flicks, S-wave Arabian tail)
 *   2. Pasture grazing (arched neck reach + jaw chewing)
 *   3. 4-beat equine walk (anatomical carpus/tarsus swing flexion + 2x head nod)
 *   4. Asymmetric 3-beat canter/gallop (suspension bounce + lead/trailing stride + streaming tail)
 *   5. Heroic stallion rear (hindleg stand, foreleg pawing, neigh jaw, heraldic half-unfurl)
 *   6. Smooth takeoff / landing 3-stage wing unfurling & folding
 *   7. Powered avian figure-8 flap (wrist-flexed upstroke + body lift heave + tucked hooves)
 *   8. Thermal dihedral soar/glide
 *   9. Mid-air hover (nose-up posture + fanned tail brake + rapid hover wingbeat)
 */
public class PegasusBlockbenchModel extends EntityModel<PegasusEntity> {
\tpublic static final ModelLayerLocation LAYER_LOCATION =
\t\t\tnew ModelLayerLocation(new ResourceLocation(RiftWorld.MODID, "pegasus_bb"), "main");

\tprivate record RestPose(ModelPart part, float px, float py, float pz, float rx, float ry, float rz) {}

\tprivate final ModelPart root;
\tprivate final ModelPart body;
\tprivate final ModelPart saddle_tack;
\tprivate final ModelPart neck_lower;
\tprivate final ModelPart neck_upper;
\tprivate final ModelPart head;
\tprivate final ModelPart head_tack;
\tprivate final ModelPart jaw;
\tprivate final ModelPart ear_l;
\tprivate final ModelPart ear_r;
\tprivate final ModelPart leg_front_upper_l;
\tprivate final ModelPart leg_front_cannon_l;
\tprivate final ModelPart leg_front_hoof_l;
\tprivate final ModelPart leg_front_upper_r;
\tprivate final ModelPart leg_front_cannon_r;
\tprivate final ModelPart leg_front_hoof_r;
\tprivate final ModelPart leg_back_thigh_l;
\tprivate final ModelPart leg_back_cannon_l;
\tprivate final ModelPart leg_back_hoof_l;
\tprivate final ModelPart leg_back_thigh_r;
\tprivate final ModelPart leg_back_cannon_r;
\tprivate final ModelPart leg_back_hoof_r;
\tprivate final ModelPart wing_1_l;
\tprivate final ModelPart wing_1_feathers_l;
\tprivate final ModelPart wing_2_l;
\tprivate final ModelPart wing_2_feathers_l;
\tprivate final ModelPart wing_3_l;
\tprivate final ModelPart wing_3_fan_l;
\tprivate final ModelPart wing_1_r;
\tprivate final ModelPart wing_1_feathers_r;
\tprivate final ModelPart wing_2_r;
\tprivate final ModelPart wing_2_feathers_r;
\tprivate final ModelPart wing_3_r;
\tprivate final ModelPart wing_3_fan_r;
\tprivate final ModelPart tail_1;
\tprivate final ModelPart tail_2;
\tprivate final ModelPart tail_3;
\tprivate final List<RestPose> restPoses;

\tpublic PegasusBlockbenchModel(ModelPart bakedRoot) {
\t\tthis.root = bakedRoot.getChild("root");
\t\tthis.body = this.root.getChild("body");
\t\tthis.saddle_tack = this.body.getChild("saddle_tack");
\t\tthis.neck_lower = this.body.getChild("neck_lower");
\t\tthis.neck_upper = this.neck_lower.getChild("neck_upper");
\t\tthis.head = this.neck_upper.getChild("head");
\t\tthis.head_tack = this.head.getChild("head_tack");
\t\tthis.jaw = this.head.getChild("jaw");
\t\tthis.ear_l = this.head.getChild("ear_l");
\t\tthis.ear_r = this.head.getChild("ear_r");
\t\tthis.leg_front_upper_l = this.body.getChild("leg_front_upper_l");
\t\tthis.leg_front_cannon_l = this.leg_front_upper_l.getChild("leg_front_cannon_l");
\t\tthis.leg_front_hoof_l = this.leg_front_cannon_l.getChild("leg_front_hoof_l");
\t\tthis.leg_front_upper_r = this.body.getChild("leg_front_upper_r");
\t\tthis.leg_front_cannon_r = this.leg_front_upper_r.getChild("leg_front_cannon_r");
\t\tthis.leg_front_hoof_r = this.leg_front_cannon_r.getChild("leg_front_hoof_r");
\t\tthis.leg_back_thigh_l = this.body.getChild("leg_back_thigh_l");
\t\tthis.leg_back_cannon_l = this.leg_back_thigh_l.getChild("leg_back_cannon_l");
\t\tthis.leg_back_hoof_l = this.leg_back_cannon_l.getChild("leg_back_hoof_l");
\t\tthis.leg_back_thigh_r = this.body.getChild("leg_back_thigh_r");
\t\tthis.leg_back_cannon_r = this.leg_back_thigh_r.getChild("leg_back_cannon_r");
\t\tthis.leg_back_hoof_r = this.leg_back_cannon_r.getChild("leg_back_hoof_r");
\t\tthis.wing_1_l = this.body.getChild("wing_1_l");
\t\tthis.wing_1_feathers_l = this.wing_1_l.getChild("wing_1_feathers_l");
\t\tthis.wing_2_l = this.wing_1_l.getChild("wing_2_l");
\t\tthis.wing_2_feathers_l = this.wing_2_l.getChild("wing_2_feathers_l");
\t\tthis.wing_3_l = this.wing_2_l.getChild("wing_3_l");
\t\tthis.wing_3_fan_l = this.wing_3_l.getChild("wing_3_fan_l");
\t\tthis.wing_1_r = this.body.getChild("wing_1_r");
\t\tthis.wing_1_feathers_r = this.wing_1_r.getChild("wing_1_feathers_r");
\t\tthis.wing_2_r = this.wing_1_r.getChild("wing_2_r");
\t\tthis.wing_2_feathers_r = this.wing_2_r.getChild("wing_2_feathers_r");
\t\tthis.wing_3_r = this.wing_2_r.getChild("wing_3_r");
\t\tthis.wing_3_fan_r = this.wing_3_r.getChild("wing_3_fan_r");
\t\tthis.tail_1 = this.body.getChild("tail_1");
\t\tthis.tail_2 = this.tail_1.getChild("tail_2");
\t\tthis.tail_3 = this.tail_2.getChild("tail_3");
\t\tthis.restPoses = this.root.getAllParts()
\t\t\t\t.map(p -> new RestPose(p, p.x, p.y, p.z, p.xRot, p.yRot, p.zRot))
\t\t\t\t.toList();
\t}

${bodyLayerMethod}

\tprivate static float rad(float deg) {
\t\treturn deg * ((float) Math.PI / 180.0F);
\t}

\tprivate static float smooth01(float x) {
\t\tfloat t = Mth.clamp(x, 0.0F, 1.0F);
\t\treturn t * t * (3.0F - 2.0F * t);
\t}

\t/** Exact Blockbench \`flip_y: true\` rotation delta (\`-rx, -ry, +rz\` in Mojang ModelPart space). */
\tprivate static void addBbDeg(ModelPart p, float dx, float dy, float dz) {
\t\tp.xRot -= rad(dx);
\t\tp.yRot -= rad(dy);
\t\tp.zRot += rad(dz);
\t}

\t/** Exact Blockbench \`flip_y: true\` translation delta (\`-dx, -dy, +dz\` in Mojang ModelPart space). */
\tprivate static void addBbPos(ModelPart p, float dx, float dy, float dz) {
\t\tp.x -= dx;
\t\tp.y -= dy;
\t\tp.z += dz;
\t}

\t@Override
\tpublic void setupAnim(PegasusEntity entity, float limbSwing, float limbSwingAmount,
\t                      float ageInTicks, float netHeadYaw, float headPitch) {
\t\tfor (RestPose rp : this.restPoses) {
\t\t\trp.part.x = rp.px;
\t\t\trp.part.y = rp.py;
\t\t\trp.part.z = rp.pz;
\t\t\trp.part.xRot = rp.rx;
\t\t\trp.part.yRot = rp.ry;
\t\t\trp.part.zRot = rp.rz;
\t\t}

\t\t// Toggle Royal Elisar saddle & golden bridle according to entity state
\t\tthis.saddle_tack.visible = entity.hasSaddle();
\t\tthis.head_tack.visible = entity.hasSaddle() || entity.isTamed();

\t\tfloat pt = entity.getRenderPartialTick();
\t\tint showcase = entity.getShowcasePose();
\t\tif (showcase == PegasusEntity.POSE_WALK) {
\t\t\tlimbSwing = ageInTicks * 0.45F + 1.1F;
\t\t\tlimbSwingAmount = 0.34F;
\t\t} else if (showcase == PegasusEntity.POSE_GALLOP) {
\t\t\tlimbSwing = ageInTicks * 0.65F + 0.75F;
\t\t\tlimbSwingAmount = 0.88F;
\t\t}

\t\tfloat rawFly = entity.getFlyProgress(pt);
\t\tfloat uFly = smooth01(rawFly);
\t\tfloat uGlide = smooth01(entity.getGlideProgress(pt));
\t\tfloat uHover = smooth01(entity.getHoverProgress(pt));
\t\tfloat uRear = smooth01(entity.getRearProgress(pt)) * (1.0F - uFly);
\t\tfloat uGraze = smooth01(entity.getGrazeProgress(pt)) * (1.0F - uFly) * (1.0F - uRear);
\t\tfloat uGround = (1.0F - uFly) * (1.0F - uRear);

\t\t// =========================================================================
\t\t// 1. IDLE, LOOK, HURT/NEIGH & GRAZE HEAD-NECK ARTICULATION
\t\t// =========================================================================
\t\tfloat clampedYaw = Mth.clamp(netHeadYaw, -45.0F, 45.0F) * (1.0F - 0.65F * uGraze);
\t\tfloat clampedPitch = Mth.clamp(headPitch, -25.0F, 25.0F) * (1.0F - 0.80F * uGraze);
\t\tfloat breath = Mth.sin(ageInTicks * 0.065F);

\t\tfloat neckLowPitch = -clampedPitch * 0.22F + breath * 1.4F;
\t\tfloat neckUpPitch = -clampedPitch * 0.16F - breath * 0.9F;
\t\tfloat headLocPitch = -clampedPitch * 0.42F + breath * 0.5F;
\t\tfloat jawOpen = 0.0F;

\t\t// Pasture grazing: arched neck reaches down to grass + rhythmic chewing
\t\tif (uGraze > 0.001F) {
\t\t\tfloat chew = 0.5F + 0.5F * Mth.sin(ageInTicks * 0.52F);
\t\t\tneckLowPitch += -38.0F * uGraze;
\t\t\tneckUpPitch += -24.0F * uGraze;
\t\t\theadLocPitch += (20.0F - chew * 3.5F) * uGraze;
\t\t\tjawOpen += (-1.5F - chew * 7.5F) * uGraze;
\t\t}

\t\t// Hurt / startle head-toss & whinny
\t\tfloat hurtFrac = entity.hurtTime > 0 ? Mth.clamp((entity.hurtTime - pt) / 10.0F, 0.0F, 1.0F) : 0.0F;
\t\tif (hurtFrac > 0.001F) {
\t\t\tfloat toss = Mth.sin(hurtFrac * (float) Math.PI);
\t\t\tneckLowPitch += 14.0F * toss;
\t\t\theadLocPitch += -18.0F * toss;
\t\t\tjawOpen += -14.0F * toss;
\t\t}

\t\t// Asymmetric living ear flicks + pinned ears when hurt/rearing
\t\tfloat earFlickL = Mth.sin(ageInTicks * 0.09F) * 3.2F + Math.max(0.0F, Mth.sin(ageInTicks * 0.23F)) * 5.0F;
\t\tfloat earFlickR = -Mth.sin(ageInTicks * 0.083F + 1.1F) * 3.0F + Math.max(0.0F, Mth.sin(ageInTicks * 0.19F + 2.4F)) * 4.5F;
\t\tfloat earPin = -18.0F * Math.max(hurtFrac, uRear * 0.55F);
\t\taddBbDeg(ear_l, earFlickL + earPin, 3.0F * uGraze, 0.0F);
\t\taddBbDeg(ear_r, earFlickR + earPin, -3.0F * uGraze, 0.0F);

\t\t// =========================================================================
\t\t// 2. GROUND LOCOMOTION: 4-BEAT WALK <-> ASYMMETRIC 3-BEAT CANTER/GALLOP
\t\t// =========================================================================
\t\tfloat moveAmt = Mth.clamp(limbSwingAmount, 0.0F, 1.15F) * uGround * (1.0F - 0.85F * uGraze);
\t\tfloat gallopBlend = smooth01((moveAmt - 0.38F) / 0.34F);
\t\tfloat walkBlend = 1.0F - gallopBlend;

\t\tfloat bodyBounceY = 0.0F;
\t\tfloat bodyPitch = 0.0F;

\t\tif (moveAmt > 0.004F) {
\t\t\tfloat w = limbSwing * 0.6662F;

\t\t\t// 4-beat equine walk phases (BL -> FL -> BR -> FR) with anatomical swing flexion
\t\t\tfloat wFL = Mth.cos(w) * 28.0F * moveAmt;
\t\t\tfloat wFR = Mth.cos(w + (float) Math.PI) * 28.0F * moveAmt;
\t\t\tfloat wBL = Mth.cos(w + (float) Math.PI * 0.75F) * 25.0F * moveAmt;
\t\t\tfloat wBR = Mth.cos(w - (float) Math.PI * 0.25F) * 25.0F * moveAmt;

\t\t\t// Fore-carpus folds backward (-Rx) on forward lift; hind-hock folds smoothly on swing
\t\t\tfloat kFL = -Math.max(0.0F, -Mth.sin(w)) * 34.0F * moveAmt;
\t\t\tfloat kFR = -Math.max(0.0F, -Mth.sin(w + (float) Math.PI)) * 34.0F * moveAmt;
\t\t\tfloat kBL = Math.max(0.0F, -Mth.sin(w + (float) Math.PI * 0.75F)) * 24.0F * moveAmt;
\t\t\tfloat kBR = Math.max(0.0F, -Mth.sin(w - (float) Math.PI * 0.25F)) * 24.0F * moveAmt;

\t\t\t// Asymmetric 3-beat gallop phases (lead foreleg vs trailing foreleg, suspension bounce)
\t\t\tfloat g = limbSwing * 0.78F;
\t\t\tfloat gFL = Mth.cos(g) * 40.0F * moveAmt;
\t\t\tfloat gFR = Mth.cos(g + 0.65F) * 38.0F * moveAmt;
\t\t\tfloat gBL = Mth.cos(g + (float) Math.PI + 0.20F) * 36.0F * moveAmt;
\t\t\tfloat gBR = Mth.cos(g + (float) Math.PI + 0.78F) * 34.0F * moveAmt;

\t\t\tfloat gkFL = -(0.25F + 0.75F * Math.max(0.0F, -Mth.sin(g))) * 46.0F * moveAmt;
\t\t\tfloat gkFR = -(0.25F + 0.75F * Math.max(0.0F, -Mth.sin(g + 0.65F))) * 44.0F * moveAmt;
\t\t\tfloat gkBL = (0.20F + 0.80F * Math.max(0.0F, -Mth.sin(g + (float) Math.PI + 0.20F))) * 30.0F * moveAmt;
\t\t\tfloat gkBR = (0.20F + 0.80F * Math.max(0.0F, -Mth.sin(g + (float) Math.PI + 0.78F))) * 28.0F * moveAmt;

\t\t\taddBbDeg(leg_front_upper_l, Mth.lerp(gallopBlend, wFL, gFL), 0.0F, 0.0F);
\t\t\taddBbDeg(leg_front_cannon_l, Mth.lerp(gallopBlend, kFL, gkFL), 0.0F, 0.0F);
\t\t\taddBbDeg(leg_front_hoof_l, Mth.lerp(gallopBlend, kFL * 0.30F, gkFL * 0.35F), 0.0F, 0.0F);

\t\t\taddBbDeg(leg_front_upper_r, Mth.lerp(gallopBlend, wFR, gFR), 0.0F, 0.0F);
\t\t\taddBbDeg(leg_front_cannon_r, Mth.lerp(gallopBlend, kFR, gkFR), 0.0F, 0.0F);
\t\t\taddBbDeg(leg_front_hoof_r, Mth.lerp(gallopBlend, kFR * 0.30F, gkFR * 0.35F), 0.0F, 0.0F);

\t\t\taddBbDeg(leg_back_thigh_l, Mth.lerp(gallopBlend, wBL, gBL), 0.0F, 0.0F);
\t\t\taddBbDeg(leg_back_cannon_l, Mth.lerp(gallopBlend, kBL, gkBL), 0.0F, 0.0F);
\t\t\taddBbDeg(leg_back_hoof_l, Mth.lerp(gallopBlend, -kBL * 0.25F, -gkBL * 0.30F), 0.0F, 0.0F);

\t\t\taddBbDeg(leg_back_thigh_r, Mth.lerp(gallopBlend, wBR, gBR), 0.0F, 0.0F);
\t\t\taddBbDeg(leg_back_cannon_r, Mth.lerp(gallopBlend, kBR, gkBR), 0.0F, 0.0F);
\t\t\taddBbDeg(leg_back_hoof_r, Mth.lerp(gallopBlend, -kBR * 0.25F, -gkBR * 0.30F), 0.0F, 0.0F);

\t\t\t// 2x walk head-neck nod vs 1x gallop suspension rock & bounce
\t\t\tfloat walkNod = Mth.cos(w * 2.0F) * 3.2F * moveAmt * walkBlend;
\t\t\tfloat gallopRock = Mth.cos(g) * 6.5F * moveAmt * gallopBlend;
\t\t\tbodyBounceY += Mth.sin(g) * 1.15F * moveAmt * gallopBlend;
\t\t\tbodyPitch += Mth.cos(g) * 4.5F * moveAmt * gallopBlend;
\t\t\tneckLowPitch += walkNod - gallopRock * 1.15F - 6.0F * gallopBlend;
\t\t\theadLocPitch += -walkNod * 0.8F + gallopRock * 0.85F + 5.0F * gallopBlend;
\t\t}

\t\t// =========================================================================
\t\t// 3. HEROIC STALLION REAR (animation.pegasus.rear)
\t\t// =========================================================================
\t\tif (uRear > 0.001F) {
\t\t\tfloat paw = Mth.sin(ageInTicks * 0.42F);
\t\t\tbodyBounceY += 3.0F * uRear;
\t\t\taddBbPos(body, 0.0F, 0.0F, 2.5F * uRear);
\t\t\tbodyPitch += 36.0F * uRear;
\t\t\tneckLowPitch += -18.0F * uRear;
\t\t\tneckUpPitch += -10.0F * uRear;
\t\t\theadLocPitch += -14.0F * uRear;
\t\t\tjawOpen += (-12.0F - 3.0F * Math.abs(paw)) * uRear;

\t\t\t// Alternating foreleg pawing in the air + braced hindlegs planted on ground
\t\t\taddBbDeg(leg_front_upper_l, (42.0F + 14.0F * paw) * uRear, 0.0F, 0.0F);
\t\t\taddBbDeg(leg_front_cannon_l, (-48.0F - 12.0F * paw) * uRear, 0.0F, 0.0F);
\t\t\taddBbDeg(leg_front_hoof_l, -16.0F * uRear, 0.0F, 0.0F);

\t\t\taddBbDeg(leg_front_upper_r, (42.0F - 14.0F * paw) * uRear, 0.0F, 0.0F);
\t\t\taddBbDeg(leg_front_cannon_r, (-48.0F + 12.0F * paw) * uRear, 0.0F, 0.0F);
\t\t\taddBbDeg(leg_front_hoof_r, -16.0F * uRear, 0.0F, 0.0F);

\t\t\taddBbDeg(leg_back_thigh_l, -35.0F * uRear, 0.0F, 0.0F);
\t\t\taddBbDeg(leg_back_cannon_l, -4.0F * uRear, 0.0F, 0.0F);
\t\t\taddBbDeg(leg_back_thigh_r, -36.0F * uRear, 0.0F, 0.0F);
\t\t\taddBbDeg(leg_back_cannon_r, -4.0F * uRear, 0.0F, 0.0F);
\t\t}

\t\t// =========================================================================
\t\t// 4. AIRBORNE BODY, LEGS & TAIL (FLAP / GLIDE / HOVER)
\t\t// =========================================================================
\t\tfloat flapRate = Mth.lerp(uHover, 0.30F, 0.46F);
\t\tfloat wPhase = (showcase == PegasusEntity.POSE_FLY_FLAP) ? (ageInTicks * 0.30F + 0.85F) : (ageInTicks * flapRate);

\t\tif (uFly > 0.001F) {
\t\t\tfloat activeBeat = 1.0F - uGlide * 0.85F;
\t\t\tbodyBounceY += Mth.cos(wPhase) * 0.85F * activeBeat * uFly;
\t\t\tbodyPitch += (11.0F * uHover - 2.5F * uGlide) * uFly;
\t\t\tneckLowPitch += (Mth.sin(wPhase) * 3.0F * activeBeat - 5.0F * uHover) * uFly;
\t\t\theadLocPitch += (-Mth.sin(wPhase) * 2.2F * activeBeat - 4.0F * uHover) * uFly;

\t\t\t// Sleekly tucked equine legs in flight (slightly lower dangle during hover)
\t\t\tfloat hoverDrop = 1.0F - 0.35F * uHover;
\t\t\taddBbDeg(leg_front_upper_l, -24.0F * hoverDrop * uFly, 0.0F, 0.0F);
\t\t\taddBbDeg(leg_front_cannon_l, -42.0F * hoverDrop * uFly, 0.0F, 0.0F);
\t\t\taddBbDeg(leg_front_hoof_l, -14.0F * hoverDrop * uFly, 0.0F, 0.0F);

\t\t\taddBbDeg(leg_front_upper_r, -20.0F * hoverDrop * uFly, 0.0F, 0.0F);
\t\t\taddBbDeg(leg_front_cannon_r, -38.0F * hoverDrop * uFly, 0.0F, 0.0F);
\t\t\taddBbDeg(leg_front_hoof_r, -12.0F * hoverDrop * uFly, 0.0F, 0.0F);

\t\t\taddBbDeg(leg_back_thigh_l, -28.0F * hoverDrop * uFly, 0.0F, 0.0F);
\t\t\taddBbDeg(leg_back_cannon_l, 18.0F * hoverDrop * uFly, 0.0F, 0.0F);
\t\t\taddBbDeg(leg_back_thigh_r, -32.0F * hoverDrop * uFly, 0.0F, 0.0F);
\t\t\taddBbDeg(leg_back_cannon_r, 20.0F * hoverDrop * uFly, 0.0F, 0.0F);
\t\t}

\t\t// Apply accumulated body & head-neck posture
\t\taddBbPos(body, 0.0F, bodyBounceY, 0.0F);
\t\taddBbDeg(body, bodyPitch, 0.0F, 0.0F);
\t\taddBbDeg(neck_lower, neckLowPitch, -clampedYaw * 0.26F, 0.0F);
\t\taddBbDeg(neck_upper, neckUpPitch, -clampedYaw * 0.22F, 0.0F);
\t\taddBbDeg(head, headLocPitch, -clampedYaw * 0.44F, 0.0F);
\t\taddBbDeg(jaw, jawOpen, 0.0F, 0.0F);

\t\t// =========================================================================
\t\t// 5. 37-BONE ZERO-CLIPPING Z-FOLD <-> TAKEOFF <-> FLAP / GLIDE / HOVER WINGS
\t\t// =========================================================================
\t\t// Ground Z-fold state (0 OBB penetrations against torso, saddle, legs & tail)
\t\tfloat foldBreath = breath * 1.2F + hurtFrac * 4.0F;
\t\tfloat gW1x = -9.2F, gW1y = -69.1F, gW1z = -97.2F + foldBreath;
\t\tfloat gF1y = 78.0F;
\t\tfloat gW2x = 0.0F, gW2y = 178.0F, gW2z = -6.0F;
\t\tfloat gF2y = -115.0F;
\t\tfloat gW3x = -2.0F, gW3y = -157.0F, gW3z = -4.0F;
\t\tfloat gF3y = 54.0F;

\t\t// Blend toward heraldic half-unfurl when rearing on ground
\t\tif (uRear > 0.001F) {
\t\t\tgW1x = Mth.lerp(uRear, gW1x, 8.0F);
\t\t\tgW1y = Mth.lerp(uRear, gW1y, -12.0F);
\t\t\tgW1z = Mth.lerp(uRear, gW1z, 24.0F);
\t\t\tgF1y = Mth.lerp(uRear, gF1y, 0.0F);
\t\t\tgW2x = Mth.lerp(uRear, gW2x, 4.0F);
\t\t\tgW2y = Mth.lerp(uRear, gW2y, 10.0F);
\t\t\tgW2z = Mth.lerp(uRear, gW2z, 14.0F);
\t\t\tgF2y = Mth.lerp(uRear, gF2y, 0.0F);
\t\t\tgW3x = Mth.lerp(uRear, gW3x, 0.0F);
\t\t\tgW3y = Mth.lerp(uRear, gW3y, 4.0F);
\t\t\tgW3z = Mth.lerp(uRear, gW3z, 10.0F);
\t\t\tgF3y = Mth.lerp(uRear, gF3y, 0.0F);
\t\t}

\t\t// Airborne target state: powered figure-8 flap <-> thermal glide <-> hover + takeoff burst
\t\tfloat takeoffBurst = Mth.sin(rawFly * (float) Math.PI) * 16.0F;
\t\tfloat s1 = Mth.sin(wPhase);
\t\tfloat s2 = Mth.sin(wPhase - 0.55F);
\t\tfloat s3 = Mth.sin(wPhase - 1.05F);
\t\tfloat upstrokeFlex = Math.max(0.0F, -s1); // avian wrist/hand flexion on recovery upstroke!

\t\t// Powered flap angles (with hover amplitude boost)
\t\tfloat ampBoost = 1.0F + 0.18F * uHover;
\t\tfloat flpW1x = Mth.cos(wPhase) * 6.0F * ampBoost + 6.0F * uHover;
\t\tfloat flpW1y = -Mth.cos(wPhase) * 5.0F + 8.0F * uHover * s1;
\t\tfloat flpW1z = s1 * 28.0F * ampBoost + takeoffBurst;
\t\tfloat flpW2x = Mth.cos(wPhase - 0.4F) * 4.0F;
\t\tfloat flpW2y = upstrokeFlex * 18.0F;
\t\tfloat flpW2z = s2 * 18.0F * ampBoost + takeoffBurst * 0.5F;
\t\tfloat flpW3x = 0.0F;
\t\tfloat flpW3y = upstrokeFlex * 16.0F;
\t\tfloat flpW3z = s3 * 14.0F * ampBoost + takeoffBurst * 0.35F;

\t\t// Soaring dihedral glide angles with subtle primary wind-flutter
\t\tfloat tremor = Mth.sin(ageInTicks * 0.24F) * 2.0F;
\t\tfloat fW1x = Mth.lerp(uGlide, flpW1x, 3.0F);
\t\tfloat fW1y = Mth.lerp(uGlide, flpW1y, 5.0F);
\t\tfloat fW1z = Mth.lerp(uGlide, flpW1z, 12.0F + tremor);
\t\tfloat fW2x = Mth.lerp(uGlide, flpW2x, 2.0F);
\t\tfloat fW2y = Mth.lerp(uGlide, flpW2y, 3.0F);
\t\tfloat fW2z = Mth.lerp(uGlide, flpW2z, 8.0F + tremor * 0.7F);
\t\tfloat fW3x = Mth.lerp(uGlide, flpW3x, 0.0F);
\t\tfloat fW3y = Mth.lerp(uGlide, flpW3y, 2.0F);
\t\tfloat fW3z = Mth.lerp(uGlide, flpW3z, 6.0F + tremor * 1.1F);

\t\t// Final continuous blend between ground/rear wing state and airborne wing state
\t\tfloat posScale = (1.0F - uFly) * (1.0F - uRear);
\t\taddBbPos(wing_1_l, 1.48F * posScale, -0.3F * posScale, 0.4F * posScale);
\t\taddBbPos(wing_1_r, -1.48F * posScale, -0.3F * posScale, 0.4F * posScale);

\t\tfloat w1x = Mth.lerp(uFly, gW1x, fW1x);
\t\tfloat w1y = Mth.lerp(uFly, gW1y, fW1y);
\t\tfloat w1z = Mth.lerp(uFly, gW1z, fW1z);
\t\tfloat f1y = Mth.lerp(uFly, gF1y, 0.0F);
\t\tfloat w2x = Mth.lerp(uFly, gW2x, fW2x);
\t\tfloat w2y = Mth.lerp(uFly, gW2y, fW2y);
\t\tfloat w2z = Mth.lerp(uFly, gW2z, fW2z);
\t\tfloat f2y = Mth.lerp(uFly, gF2y, 0.0F);
\t\tfloat w3x = Mth.lerp(uFly, gW3x, fW3x);
\t\tfloat w3y = Mth.lerp(uFly, gW3y, fW3y);
\t\tfloat w3z = Mth.lerp(uFly, gW3z, fW3z);
\t\tfloat f3y = Mth.lerp(uFly, gF3y, 0.0F);

\t\taddBbDeg(wing_1_l, w1x, w1y, w1z);
\t\taddBbDeg(wing_1_feathers_l, 0.0F, f1y, 0.0F);
\t\taddBbDeg(wing_2_l, w2x, w2y, w2z);
\t\taddBbDeg(wing_2_feathers_l, 0.0F, f2y, 0.0F);
\t\taddBbDeg(wing_3_l, w3x, w3y, w3z);
\t\taddBbDeg(wing_3_fan_l, 0.0F, f3y, 0.0F);

\t\taddBbDeg(wing_1_r, w1x, -w1y, -w1z);
\t\taddBbDeg(wing_1_feathers_r, 0.0F, -f1y, 0.0F);
\t\taddBbDeg(wing_2_r, w2x, -w2y, -w2z);
\t\taddBbDeg(wing_2_feathers_r, 0.0F, -f2y, 0.0F);
\t\taddBbDeg(wing_3_r, w3x, -w3y, -w3z);
\t\taddBbDeg(wing_3_fan_r, 0.0F, -f3y, 0.0F);

\t\t// =========================================================================
\t\t// 6. CASCADING 3-SEGMENT ARABIAN TAIL PLUME
\t\t// =========================================================================
\t\tfloat tailStream = -18.0F * gallopBlend * moveAmt - 14.0F * uFly * (1.0F - uHover) + 12.0F * uHover * uFly - 20.0F * uRear;
\t\tfloat tailSwayFreq = Mth.lerp(uFly, 0.07F, 0.14F);
\t\tfloat tailSway1 = Mth.cos(ageInTicks * tailSwayFreq) * (4.5F + 3.0F * moveAmt);
\t\tfloat tailSway2 = Mth.sin(ageInTicks * tailSwayFreq) * (6.0F + 4.0F * moveAmt);
\t\tfloat tailSway3 = Mth.sin(ageInTicks * tailSwayFreq - 0.7F) * (7.0F + 4.5F * moveAmt);

\t\taddBbDeg(tail_1, Mth.sin(ageInTicks * 0.055F) * 2.0F + tailStream, tailSway1, 0.0F);
\t\taddBbDeg(tail_2, tailStream * 0.55F, tailSway2, 0.0F);
\t\taddBbDeg(tail_3, tailStream * 0.35F, tailSway3, 0.0F);
\t}

\t@Override
\tpublic void renderToBuffer(PoseStack poseStack, VertexConsumer vertexConsumer, int packedLight,
\t                           int packedOverlay, float red, float green, float blue, float alpha) {
\t\tthis.root.render(poseStack, vertexConsumer, packedLight, packedOverlay, red, green, blue, alpha);
\t}
}
`;
}

const outDir = join(ROOT, "mod/src/main/java/ru/aiforge/riftworld/client/model");
mkdirSync(outDir, { recursive: true });

const lioRaw = readFileSync(join(ROOT, "reports/blockbench_models/LiopleurodonBlockbenchRaw.java.txt"), "utf-8");
const pegRaw = readFileSync(join(ROOT, "reports/blockbench_models/PegasusBlockbenchRaw.java.txt"), "utf-8");

writeFileSync(join(outDir, "LiopleurodonBlockbenchModel.java"), buildLiopleurodonJava(lioRaw), "utf-8");
writeFileSync(join(outDir, "PegasusBlockbenchModel.java"), buildPegasusJava(pegRaw), "utf-8");
console.log("[emit] Wrote LiopleurodonBlockbenchModel.java and PegasusBlockbenchModel.java");
